begin;set local role postgres;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions,pgtap;select plan(80);
select ok(to_regclass(format('public.%I',table_name))is not null,format('table %s exists',table_name))from unnest(array['erp_import_manifests','erp_import_mappings','erp_import_jobs','erp_import_batches','erp_import_items','erp_import_rejections','erp_import_reconciliations'])names(table_name);
select ok(c.relrowsecurity,format('RLS enabled on %s',c.relname))from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public'and c.relname=any(array['erp_import_manifests','erp_import_mappings','erp_import_jobs','erp_import_batches','erp_import_items','erp_import_rejections','erp_import_reconciliations'])order by c.relname;
select ok(not has_table_privilege('anon',format('public.%I',table_name),'SELECT'),format('anon cannot read %s',table_name))from unnest(array['erp_import_manifests','erp_import_mappings','erp_import_jobs','erp_import_batches','erp_import_items','erp_import_rejections','erp_import_reconciliations'])names(table_name);
select ok(has_table_privilege('authenticated',format('public.%I',table_name),'SELECT'),format('authenticated reads %s under RLS',table_name))from unnest(array['erp_import_manifests','erp_import_mappings','erp_import_jobs','erp_import_batches','erp_import_items','erp_import_rejections','erp_import_reconciliations'])names(table_name);
select ok(not has_table_privilege('authenticated',format('public.%I',table_name),'INSERT'),format('authenticated cannot insert %s',table_name))from unnest(array['erp_import_manifests','erp_import_mappings','erp_import_jobs','erp_import_batches','erp_import_items','erp_import_rejections','erp_import_reconciliations'])names(table_name);
select is((select count(*)::integer from public.erp_permissions where key in('import.read','import.execute','import.audit')),3,'three M14 permissions exist');
select ok(not has_function_privilege('anon',signature,'EXECUTE'),format('anon cannot execute %s',signature))from(values('public.erp_register_import_manifest(uuid,text,text,text,text,timestamptz,jsonb)'),('public.erp_open_import_job(uuid,uuid,text,bigint,bigint)'),('public.erp_open_import_batch(uuid,uuid,text,integer,text,integer,bigint)'),('public.erp_record_import_item(uuid,uuid,text,text,text,bigint)'),('public.erp_finalize_import_batch(uuid,uuid,text)'))f(signature);
select ok(not has_function_privilege('authenticated',signature,'EXECUTE'),format('authenticated cannot execute %s',signature))from(values('public.erp_register_import_manifest(uuid,text,text,text,text,timestamptz,jsonb)'),('public.erp_open_import_job(uuid,uuid,text,bigint,bigint)'),('public.erp_open_import_batch(uuid,uuid,text,integer,text,integer,bigint)'),('public.erp_record_import_item(uuid,uuid,text,text,text,bigint)'),('public.erp_finalize_import_batch(uuid,uuid,text)'))f(signature);
select ok(has_function_privilege('service_role',signature,'EXECUTE'),format('service role executes %s',signature))from(values('public.erp_register_import_manifest(uuid,text,text,text,text,timestamptz,jsonb)'),('public.erp_open_import_job(uuid,uuid,text,bigint,bigint)'),('public.erp_open_import_batch(uuid,uuid,text,integer,text,integer,bigint)'),('public.erp_record_import_item(uuid,uuid,text,text,text,bigint)'),('public.erp_finalize_import_batch(uuid,uuid,text)'))f(signature);
select ok(p.prosecdef,format('%s is security definer',p.proname))from pg_proc p where p.oid=any(array['public.erp_register_import_manifest(uuid,text,text,text,text,timestamptz,jsonb)'::regprocedure,'public.erp_open_import_job(uuid,uuid,text,bigint,bigint)'::regprocedure,'public.erp_open_import_batch(uuid,uuid,text,integer,text,integer,bigint)'::regprocedure,'public.erp_record_import_item(uuid,uuid,text,text,text,bigint)'::regprocedure,'public.erp_finalize_import_batch(uuid,uuid,text)'::regprocedure])order by p.proname;
select ok(exists(select 1 from pg_constraint where conname=constraint_name),format('constraint %s exists',constraint_name))from unnest(array['erp_import_manifests_tenant_id_idempotency_key_key','erp_import_manifests_tenant_id_source_sha256_schema_version_key','uq_import_mapping_context','erp_import_jobs_tenant_id_idempotency_key_key','erp_import_batches_tenant_id_job_id_domain_sequence_key','erp_import_batches_tenant_id_batch_hash_key','erp_import_items_tenant_id_batch_id_canonical_key_key','erp_import_items_tenant_id_batch_id_source_key_hash_key','erp_import_reconciliations_tenant_id_batch_id_key','erp_import_rejections_tenant_id_batch_id_item_id_error_code_key'])names(constraint_name);
select ok(pg_get_functiondef(signature::regprocedure)like'%broker only%',format('%s is broker only',signature))from(values('public.erp_register_import_manifest(uuid,text,text,text,text,timestamptz,jsonb)'),('public.erp_open_import_job(uuid,uuid,text,bigint,bigint)'),('public.erp_open_import_batch(uuid,uuid,text,integer,text,integer,bigint)'),('public.erp_record_import_item(uuid,uuid,text,text,text,bigint)'),('public.erp_finalize_import_batch(uuid,uuid,text)'))f(signature);
select ok(exists(select 1 from pg_policies where schemaname='public'and tablename=table_name and qual like'%import.%'),format('%s policy checks import permission',table_name))from unnest(array['erp_import_manifests','erp_import_mappings','erp_import_jobs','erp_import_batches','erp_import_items'])names(table_name);
select is((select count(*)::integer from public.erp_import_manifests),0,'zero manifests');select is((select count(*)::integer from public.erp_import_jobs),0,'zero jobs');select is((select count(*)::integer from public.erp_import_items),0,'zero items');select is((select count(*)::integer from public.erp_import_reconciliations),0,'zero reconciliations');
select * from finish();rollback;
